H["Trivia.Finished"] = function(v) TV.ov = v TV.fin = true end
H["Trivia.Question"] = function(v) TV.q = v end
H["Trivia.AnswerResult"] = function(v)
    TV.res = v
    if type(v) ~= "table" then return end
    if v.questionId and type(v.correctAnswer) == "string" and v.correctAnswer ~= "" then
        TV.bank[v.questionId] = v.correctAnswer
        TV.save()
    end
    if v.correct then S.triviaRight = S.triviaRight + 1 end
end
function TV.pick(q)
    local known = TV.bank[q.questionId]
    if known then for i, a in ipairs(q.answers) do if a == known then return i end end end
    local best, bl = 1, -1
    for i, a in ipairs(q.answers) do if #a > bl then best, bl = i, #a end end
    return best
end
function TV.overview()
    TV.ov = nil
    send("Trivia", "RequestOverview")
    local t0 = os.clock()
    while not TV.ov and os.clock() - t0 < 3 do task.wait(0.1) end
    return TV.ov
end
function TV.run()
    local ov = TV.overview()
    if type(ov) ~= "table" then return end
    if ov.completed or (num(ov.total) > 0 and num(ov.answered) >= num(ov.total)) then
        S.status.trivia = string.format(L["Done today  ·  %d/%d correct"], num(ov.correct), num(ov.total))
        return
    end
    local rb = workspace:FindFirstChild("rbx-build")
    local rig = rb and rb:FindFirstChild("Questions") and rb.Questions:FindFirstChild("Rig")
    if not rig then S.status.trivia = L["Quiz host not found"] return end
    if not grab("trivia", 10) then return end
    local r = hrp()
    local back = r and r.CFrame
    pcall(function()
        S.status.trivia = L["Playing"]
        tp(rig:GetPivot() * CFrame.new(0, 0, -6))
        task.wait(1)
        TV.q, TV.fin = nil, false
        send("Trivia", "Start")
        local t0, lastQ, sid = os.clock(), os.clock(), nil
        while RUNNING and on("cc_trivia") and os.clock() - t0 < 120 do
            local q = TV.q
            if q then
                TV.q, TV.res = nil, nil
                sid = q.sessionId
                lastQ = os.clock()
                task.wait(0.8)
                send("Trivia", "Answer", { sessionId = q.sessionId, questionId = q.questionId, answerIndex = TV.pick(q) })
                local t1 = os.clock()
                while not TV.res and os.clock() - t1 < 5 do task.wait(0.1) end
                if TV.res and TV.res.isLast then break end
                task.wait(1)
                send("Trivia", "Next", { sessionId = q.sessionId })
            elseif os.clock() - lastQ > 8 then
                break
            end
            task.wait(0.1)
        end
        if sid then send("Trivia", "Leave", { sessionId = sid }) end
    end)
    if back then tp(back) end
    free("trivia")
end
function TV.loop()
    local last = -1e9
    while RUNNING do
        pcall(function()
            if on("cc_trivia") and os.clock() - last > 60 then
                last = os.clock()
                TV.run()
            elseif not on("cc_trivia") then
                S.status.trivia = nil
            end
        end)
        task.wait(2)
    end
end
local MT = { done = setmetatable({}, { __mode = "k" }) }
function MT.ready()
    local out = {}
    for _, m in ipairs(CollectionService:GetTagged("AdminMeteorDrop")) do
        if not MT.done[m] and m.Parent then
            local landed = num(m:GetAttribute("LandedAt"))
            if landed > 0 and now() >= landed + 0.2 then
                local pp = m:FindFirstChild("AdminMeteorPickup", true)
                if pp and pp:IsA("ProximityPrompt") and pp.Enabled then out[#out + 1] = { m = m, pp = pp } end
            end
        end
    end
    return out
end
function MT.loop()
    while RUNNING do
        pcall(function()
            if not on("cc_meteor") then return end
            local list = MT.ready()
            if #list == 0 or not grab("meteor", 2) then return end
            local r = hrp()
            local back = r and r.CFrame
            pcall(function()
                for _, it in ipairs(list) do
                    local par = it.pp.Parent
                    local pos = (par:IsA("Attachment") and par.WorldPosition) or (par:IsA("BasePart") and par.Position) or it.m:GetPivot().Position
                    tp(CFrame.new(pos + Vector3.new(0, 3, 0)))
                    task.wait(0.35)
                    firePrompt(it.pp)
                    MT.done[it.m] = true
                    S.meteors = S.meteors + 1
                    task.wait(0.25)
                end
            end)
            if back then tp(back) end
            free("meteor")
        end)
        task.wait(0.5)
    end
end
local PO = { stock = {}, nextDrink = {} }
H["PotionShop.StockSync"] = function(v)
    if type(v) ~= "table" or type(v.typeIds) ~= "table" then return end
    for i, id in ipairs(v.typeIds) do PO.stock[id] = num(v.stocks and v.stocks[i]) end
    PO.restockAt = v.restockAt
end
H["PotionShop.RestockGranted"] = H["PotionShop.StockSync"]
H["PotionShop.BuyResult"] = function(v) if type(v) == "table" and num(v.purchasedCount) > 0 then S.bought = S.bought + num(v.purchasedCount) end end
function PO.price(id)
    local ok, p = pcall(function() return G.Bal.PotionShop.Potions[id].GemPrice end)
    return ok and num(p) or 0
end
function PO.tool(id)
    local function scan(par)
        if not par then return nil end
        for _, t in ipairs(par:GetChildren()) do
            if t:IsA("Tool") and t:GetAttribute("PotionId") ~= nil and t:GetAttribute("PotionTypeId") == id then return t end
        end
    end
    return scan(lp:FindFirstChild("Backpack")) or scan(lp.Character)
end
function PO.duration(id)
    local ok, d = pcall(function() return G.Pot.Types[id].Duration end)
    return ok and num(d) > 0 and num(d) or 300
end
function PO.loop()
    local lastBuy = -1e9
    while RUNNING do
        pcall(function()
            if on("cc_buypot") and os.clock() - lastBuy > 20 then
                lastBuy = os.clock()
                send("PotionShop", "StockRequest", {})
                task.wait(1.2)
                for _, nm in ipairs(picked("cc_buylist")) do
                    local id = POT_ID[nm] or nm
                    if num(PO.stock[id]) > 0 and num(val("Gems")) >= PO.price(id) then
                        send("PotionShop", "BuyRequest", { typeId = id, quantity = 1 })
                        PO.stock[id] = num(PO.stock[id]) - 1
                        task.wait(0.8)
                    end
                end
            end
            if on("cc_drink") then
                for _, nm in ipairs(picked("cc_drinklist")) do
                    local id = POT_ID[nm] or nm
                    if os.clock() >= (PO.nextDrink[id] or 0) then
                        local tool = PO.tool(id)
                        local h = hum()
                        if tool and h and not LOCK.owner then
                            pcall(function() h:EquipTool(tool) end)
                            task.wait(0.35)
                            pcall(function() tool:Activate() end)
                            task.wait(0.6)
                            pcall(function() h:UnequipTools() end)
                            PO.nextDrink[id] = os.clock() + PO.duration(id) - 3
                            S.drank = S.drank + 1
                        end
                    end
                end
            end
        end)
        task.wait(2)
    end
end
local DW = { PLACE = 137788107989391, legs = 0, uturns = 0, unstuck = 0, dir = 1, lane = 2 }
DW.inWorld = game.PlaceId == DW.PLACE
DW.FALLBACK = { x0 = -2276, x1 = 1182, zs = { -239.9, -225.1, -210.3 }, y = -28.2 }
DW.BRAKE = 90
function DW.travel(where)
    local rf = RS:FindFirstChild("DriveExperienceRequest")
    if not rf then notify(L["Travel is not available here"]) return end
    notify(where == "DriveWorld" and L["Going to Drive World"] or L["Going back to your collection"])
    task.spawn(function()
        local ok, a, b = pcall(function() return rf:InvokeServer("Travel", where) end)
        if ok and type(a) == "table" and a.Ok == false then notify(tostring(a.Message or L["Travel failed"])) end
        if ok and a == false and b then notify(tostring(b)) end
    end)
end
function DW.car()
    local pc = workspace:FindFirstChild("PlayerCars")
    if not pc then return nil end
    for _, m in ipairs(pc:GetChildren()) do
        if m:GetAttribute("OwnerUserId") == lp.UserId and m.PrimaryPart then return m end
    end
end
function DW.carList()
    local Cars = G.Cars
    local tpl = RS:FindFirstChild("Assets") and RS.Assets:FindFirstChild("VehicleSpawnTemplates")
    local owned = val("Cars")
    local rows, map = {}, {}
    if not (Cars and tpl and type(owned) == "table") then return { "Best Car" }, map end
    for id, c in pairs(owned) do
        local def = Cars[c.Template]
        if def and def.Model and tpl:FindFirstChild(def.Model) then
            rows[#rows + 1] = { nm = tostring(def.DisplayName or c.Template), id = id, model = def.Model, score = num(def.RarityTier) * 1e15 + num(def.CashPerSecond) }
        end
    end
    table.sort(rows, function(a, b) return a.score > b.score end)
    local list = { "Best Car" }
    for _, r in ipairs(rows) do
        if not map[r.nm] then
            list[#list + 1] = r.nm
            map[r.nm] = r
        end
    end
    return list, map
end
function DW.bestCar()
    local pickName = Opt and Opt.cc_drcar and Opt.cc_drcar.Value
    if pickName and pickName ~= "Best Car" then
        local _, map = DW.carList()
        local r = map[pickName]
        if r then return r.id, r.model end
    end
    local Cars = G.Cars
    local tpl = RS:FindFirstChild("Assets") and RS.Assets:FindFirstChild("VehicleSpawnTemplates")
    local owned = val("Cars")
    if not (Cars and tpl and type(owned) == "table") then return nil end
    local pick, best, model
    for id, c in pairs(owned) do
        local def = Cars[c.Template]
        if def and def.Model and tpl:FindFirstChild(def.Model) then
            local score = num(def.RarityTier) * 1e15 + num(def.CashPerSecond)
            if not best or score > best then pick, best, model = id, score, def.Model end
        end
    end
    return pick, model
end
function DW.spawn()
    local id, model = DW.bestCar()
    if not id then return false, "No car to spawn" end
    local rf = RS:FindFirstChild("RequestCarSpawn")
    if not rf then return false, "Spawning not available" end
    local pos = lp:GetAttribute("DriveParkingPosition")
    local r = hrp()
    if typeof(pos) ~= "Vector3" then pos = r and r.Position or Vector3.zero end
    if r then tp(CFrame.new(pos + Vector3.new(8, 4, 0))) task.wait(0.5) end
    local ok, a, b = pcall(function() return rf:InvokeServer(model, CFrame.new(pos + Vector3.new(0, 2, 0)), id) end)
    task.wait(1.5)
    if ok and a then return true end
    return false, tostring(b or a or "Spawn failed")
end
function DW.seat(car)
    local seat = car:FindFirstChild("DriveSeat", true)
    local h = hum()
    if not (seat and h) then return false end
    if h.SeatPart == seat then return true end
    pcall(function() lp.Character:PivotTo(seat.CFrame + Vector3.new(0, 3, 0)) end)
    task.wait(0.3)
    pcall(function() seat:Sit(h) end)
    task.wait(0.8)
    return h.SeatPart == seat
end
function DW.route()
    if DW.r and os.clock() - DW.r.at < 30 then return DW.r end
    local rb = workspace:FindFirstChild("rbx-driving")
    local hw = rb and rb:FindFirstChild("Roads") and rb.Roads:FindFirstChild("Highway1Left")
    if not hw then
        local fb = DW.FALLBACK
        DW.r = DW.r or { x0 = fb.x0 + 120, x1 = fb.x1 - 120, zs = fb.zs, y = fb.y, at = os.clock() }
        return DW.r
    end
    local segs = {}
    for _, s in ipairs(hw:GetChildren()) do
        local l = s:FindFirstChild("Lanes")
        if l then
            local parts = {}
            for _, p in ipairs(l:GetChildren()) do if p:IsA("BasePart") then parts[#parts + 1] = p end end
            local p = parts[1]
            if p and #parts >= 3 and math.abs(p.CFrame.LookVector.Z) < 0.005 and math.abs(p.CFrame.LookVector.X) > 0.99 then
                local zs = {}
                for _, q in ipairs(parts) do zs[#zs + 1] = q.Position.Z end
                table.sort(zs)
                segs[#segs + 1] = { x0 = p.Position.X - p.Size.Z / 2, x1 = p.Position.X + p.Size.Z / 2, zs = zs, y = p.Position.Y + p.Size.Y / 2, len = p.Size.Z }
            end
        end
    end
    local best
    for _, anchor in ipairs(segs) do
        local x0, x1 = anchor.x0, anchor.x1
        local grew = true
        while grew do
            grew = false
            for _, s in ipairs(segs) do
                if math.abs(s.zs[2] - anchor.zs[2]) < 1 then
                    if s.x1 >= x0 - 6 and s.x0 < x0 then x0 = s.x0 grew = true end
                    if s.x0 <= x1 + 6 and s.x1 > x1 then x1 = s.x1 grew = true end
                end
            end
        end
        if not best or (x1 - x0) > (best.x1 - best.x0) then best = { x0 = x0, x1 = x1, zs = anchor.zs, y = anchor.y } end
    end
    local fb = DW.FALLBACK
    if not best or (best.x1 - best.x0) < (fb.x1 - fb.x0) - 200 then best = fb end
    if DW.r and (DW.r.x1 - DW.r.x0) >= (best.x1 - best.x0) - 240 then DW.r.at = os.clock() return DW.r end
    DW.r = { x0 = best.x0 + 120, x1 = best.x1 - 120, zs = best.zs, y = best.y, at = os.clock() }
    return DW.r
end
local GHOST_CODE = [[
local ok, C = pcall(require, game:GetService("ReplicatedStorage").Client.Traffic.Collision)
if ok and type(C) == "table" and not C.__cwPatched then
    C.__cwPatched = true
    local orig = C.Apply
    C.Apply = function(...)
        local p = game:GetService("Players").LocalPlayer
        if p and p:GetAttribute("cw_ghost") == true then return end
        return orig(...)
    end
end
]]
function DW.ghost(v)
    pcall(function() lp:SetAttribute("cw_ghost", v == true) end)
    if not v or DW.patched or not run_on_actor then return end
    local n = 0
    local ps = lp:FindFirstChild("PlayerScripts")
    for _, a in ipairs(ps and ps:GetChildren() or {}) do
        if a:IsA("Actor") and a.Name:find("HighwayTraffic") and pcall(run_on_actor, a, GHOST_CODE) then n = n + 1 end
    end
    DW.patched = n > 0
end
onClean(function() pcall(function() lp:SetAttribute("cw_ghost", false) end) end)
function DW.tune(car, mult)
    local raw = car:GetAttribute("RuntimeTune")
    if type(raw) ~= "string" then return end
    env.__CW_DCC_TUNE = env.__CW_DCC_TUNE or {}
    local key = tostring(car:GetAttribute("CarId") or car.Name)
    if not raw:find('"cwBoost"', 1, true) then env.__CW_DCC_TUNE[key] = raw end
    local orig = env.__CW_DCC_TUNE[key]
    if not orig then return end
    if mult <= 1 then
        if raw ~= orig then car:SetAttribute("RuntimeTune", orig) end
        return
    end
    DW.encCache = DW.encCache or {}
    local ck = key .. "|" .. tostring(mult) .. "|" .. #orig
    if DW.encCache[ck] then
        if raw ~= DW.encCache[ck] then car:SetAttribute("RuntimeTune", DW.encCache[ck]) end
        return
    end
    local ok, t = pcall(function() return HttpService:JSONDecode(orig) end)
    if not ok or type(t) ~= "table" then return end
    if t.TopSpeedKmh then t.TopSpeedKmh = t.TopSpeedKmh * mult end
    if type(t.Engine) == "table" then
        if t.Engine.PowerPS then t.Engine.PowerPS = t.Engine.PowerPS * mult end
        if t.Engine.TorqueNm then t.Engine.TorqueNm = t.Engine.TorqueNm * mult end
    end
    t.cwBoost = mult
    local enc = HttpService:JSONEncode(t)
    if count(DW.encCache) > 20 then DW.encCache = {} end
    DW.encCache[ck] = enc
    if raw ~= enc then car:SetAttribute("RuntimeTune", enc) end
end
function DW.mult()
    if on("cc_drive") then return 1 end
    if on("cc_mboost") and Opt.cc_mboostval then return Opt.cc_mboostval.Value end
    return 1
end
function DW.input()
