onClean(DW.release)
function DW.place(car, r, x)
    local z = r.zs[DW.lane] or r.zs[2]
    local pos = Vector3.new(x, r.y + 3, z)
    car:PivotTo(CFrame.lookAt(pos, pos + Vector3.new(DW.dir, 0, 0)))
    pcall(function()
        car.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
        car.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
    end)
end
function DW.stop()
    if not DW.active then return end
    DW.active = false
    DW.release()
    local c = DW.car()
    if c then pcall(DW.tune, c, 1) end
    DW.ghost(false)
end
function DW.lock(car, root, z)
    local cf = root.CFrame
    local p = cf.Position
    local f = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
    if f.Magnitude < 0.1 then return end
    f = f.Unit
    local ang = math.atan2(f.Z * DW.dir, f.X * DW.dir)
    local dz = z - p.Z
    local v = root.AssemblyLinearVelocity
    if math.abs(dz) > 4 or math.abs(ang) > 0.25 then
        local fwd = math.max(v.X * DW.dir, 0)
        local at = Vector3.new(p.X, p.Y, z)
        local want = CFrame.lookAt(at, at + Vector3.new(DW.dir, 0, 0))
        car:PivotTo(want * cf:Inverse() * car:GetPivot())
        local nv = Vector3.new(DW.dir * fwd, 0, 0)
        for _, bp in ipairs(car:GetDescendants()) do
            if bp:IsA("BasePart") and not bp.Anchored then
                pcall(function() bp.AssemblyLinearVelocity = nv bp.AssemblyAngularVelocity = Vector3.zero end)
            end
        end
        return
    end
    local vx = v.X
    if DW.brakeEnd then
        local cap = math.sqrt(2 * DW.BRAKE * math.max((DW.brakeEnd - p.X) * DW.dir, 0)) + 4
        if vx * DW.dir > cap then vx = DW.dir * cap end
    end
    root.AssemblyLinearVelocity = Vector3.new(vx, v.Y, math.clamp(dz * 8, -20, 20))
    local av = root.AssemblyAngularVelocity
    root.AssemblyAngularVelocity = Vector3.new(av.X * 0.5, math.clamp(ang * 12, -3, 3), av.Z * 0.5)
end
function DW.drive(car, r)
    local VI = DW.input()
    if not (VI and VI.Pad) then S.status.drive = L["Controls not found"] task.wait(2) return end
    local root = car.PrimaryPart
    local lockConn = RunService.PreSimulation:Connect(function()
        if DW.turning or not (car.Parent and root.Parent) then return end
        pcall(DW.lock, car, root, r.zs[DW.lane] or r.zs[2])
    end)
    track(lockConn)
    pcall(DW.driveLoop, car, r, VI, root)
    DW.brakeEnd = nil
    DW.turning = false
    lockConn:Disconnect()
end
function DW.driveLoop(car, r, VI, root)
    local stuckSince, lastTune = nil, 0
    while RUNNING and on("cc_drive") and car.Parent and root.Parent do
        local p = root.Position
        local sps = math.max(root.AssemblyLinearVelocity.X * DW.dir, 0)
        local kmh = sps * 0.9
        if os.clock() - lastTune > 1 then
            lastTune = os.clock()
            pcall(DW.tune, car, DW.mult())
        end
        if math.abs(p.Z - r.zs[2]) > 60 or math.abs(p.Y - r.y) > 25 then return end
        local endX = DW.dir == 1 and r.x1 or r.x0
        if (endX - p.X) * DW.dir <= sps * sps / (2 * DW.BRAKE) + 30 then
            S.status.drive = L["Slowing for turn"]
            DW.brakeEnd = endX
            local tb = os.clock()
            while os.clock() - tb < 12 and car.Parent and root.Parent do
                DW.hold(VI)
                VI.Pad.Throttle = 0 VI.Pad.Steer = 0 VI.Pad.Brake = 1
                if root.AssemblyLinearVelocity.X * DW.dir < 10 or (endX - root.Position.X) * DW.dir <= 0 then break end
                RunService.Heartbeat:Wait()
            end
            DW.brakeEnd = nil
            S.status.drive = L["Turning around"]
            DW.turning = true
            VI.Pad.Brake = 0
            local v = root.AssemblyLinearVelocity
            local spd = math.min(Vector3.new(v.X, 0, v.Z).Magnitude, 15)
            DW.dir = -DW.dir
            DW.place(car, r, root.Position.X)
            local nv = Vector3.new(DW.dir * spd, 0, 0)
            for _, bp in ipairs(car:GetDescendants()) do
                if bp:IsA("BasePart") and not bp.Anchored then
                    pcall(function() bp.AssemblyLinearVelocity = nv bp.AssemblyAngularVelocity = Vector3.zero end)
                end
            end
            DW.legs = DW.legs + 1
            DW.turning = false
            RunService.Heartbeat:Wait()
        else
            DW.hold(VI)
            VI.Pad.Handbrake = false
            VI.Pad.Brake = 0
            VI.Pad.Throttle = 1
            VI.Pad.Steer = 0
            if kmh < 4 then
                stuckSince = stuckSince or os.clock()
                if os.clock() - stuckSince > 4 then
                    stuckSince = nil
                    DW.unstuck = DW.unstuck + 1
                    DW.place(car, r, p.X + DW.dir * 8)
                end
            else
                stuckSince = nil
            end
            S.status.drive = string.format(L["Driving  ·  %d km/h"], math.floor(kmh))
            RunService.Heartbeat:Wait()
        end
    end
end
function DW.manualLoop()
    while RUNNING do
        pcall(function()
            if not DW.inWorld or on("cc_drive") then return end
            local car = DW.car()
            if car then DW.tune(car, DW.mult()) end
        end)
        task.wait(1)
    end
end
onClean(function() pcall(function() local c = DW.car() if c then DW.tune(c, 1) end end) end)
function DW.loop()
    while RUNNING do
        pcall(function()
            if not on("cc_drive") then DW.stop() S.status.drive = nil return end
            if not DW.inWorld then S.status.drive = L["Go to Drive World first"] return end
            DW.active = true
            DW.t0 = DW.t0 or os.clock()
            local car = DW.car()
            if car and DW.wantRespawn then
                DW.wantRespawn = false
                local id = DW.bestCar()
                if id and car:GetAttribute("CarId") ~= id then car = nil end
            end
            if not car then
                S.status.drive = L["Spawning your car"]
                local ok, why = DW.spawn()
                if not ok then S.status.drive = L["Spawn failed: "] .. tostring(why):sub(1, 40) task.wait(3) end
                return
            end
            if not DW.seat(car) then S.status.drive = L["Getting in"] return end
            local r = DW.route()
            if not r then S.status.drive = L["Highway not loaded"] return end
            DW.ghost(on("cc_ghost"))
            DW.tune(car, DW.mult())
            local p = car.PrimaryPart.Position
            if not (p.X > r.x0 - 200 and p.X < r.x1 + 200 and math.abs(p.Z - r.zs[2]) < 40 and math.abs(p.Y - r.y) < 15) then
                DW.dir, DW.lane = 1, 2
                S.status.drive = L["Moving to the highway"]
                DW.place(car, r, r.x0 + 20)
                task.wait(1.2)
                return
            end
            DW.drive(car, r)
        end)
        task.wait(0.3)
    end
end
