local DQ = { REQ = 100 }
function DQ.npc()
    local rb = workspace:FindFirstChild("rbx-build")
    local dq = rb and rb:FindFirstChild("DriveQuest")
    local npc = dq and dq:FindFirstChild("Npc")
    if npc then return npc end
    for _, m in ipairs(rb and rb:GetDescendants() or {}) do
        if m:IsA("Model") and m:GetAttribute("DriveQuestNPC") == true then return m end
    end
end
function DQ.invoke(action, arg)
    local rf = RS:FindFirstChild("DriveQuestRequest")
    if not rf then return nil end
    local ok, res = pcall(function() return rf:InvokeServer(action, arg) end)
    return ok and type(res) == "table" and res or nil
end
function DQ.step()
    local q = val("DriveQuest")
    if type(q) ~= "table" then q = {} end
    local miles = math.floor(num(val("DrivingMiles")))
    if q.Claimed and not q.Reveal then S.status.dq = L["Limited car claimed"] return end
    if q.Started and miles < DQ.REQ then S.status.dq = string.format(L["Driving  ·  %d/%d miles"], miles, DQ.REQ) return end
    local npc = DQ.npc()
    if not npc then
        S.status.dq = q.Started and L["Ready! Go to your collection"] or L["Starts at your collection"]
        return
    end
    if not grab("quest", 5) then return end
    local r = hrp()
    local back = r and r.CFrame
    pcall(function()
        tp(npc:GetPivot() * CFrame.new(0, 0, -5))
        task.wait(1)
        if not q.Started then
            local res = DQ.invoke("Start")
            S.status.dq = res and res.Ok and L["Quest started"] or (L["Start failed: "] .. tostring(res and res.Message or "?"):sub(1, 30))
        else
            local res = DQ.invoke("Roll")
            if res and res.Ok and type(res.Roll) == "table" then
                task.wait(1)
                DQ.invoke("Seen", res.Roll.id)
                S.status.dq = L["Limited car claimed"]
                notify(L["Claimed the 100 mile limited car"])
            else
                S.status.dq = L["Claim failed: "] .. tostring(res and res.Message or "?"):sub(1, 30)
            end
        end
    end)
    if back then tp(back) end
    free("quest")
end
function DQ.loop()
    local last = -1e9
    while RUNNING do
        if on("cc_dq") and os.clock() - last > 20 then
            last = os.clock()
            pcall(DQ.step)
        elseif not on("cc_dq") then
            S.status.dq = nil
        end
        task.wait(1)
    end
end
