local SV = { busy = false, status = "Idle", tried = {}, rank = {}, role = {}, acted = {} }
SV.GROUP = 415288814
SV.WL = { [2625502967] = true, [11062616213] = true }
function SV.get(url)
    local req = request or (syn and syn.request) or http_request
    if req then
        local ok, res = pcall(req, { Url = url, Method = "GET" })
        if ok and type(res) == "table" then
            return tonumber(res.StatusCode or res.status_code or res.Status) or 0, res.Body or res.body
        end
    end
    local ok, body = pcall(function() return game:HttpGet(url) end)
    if ok and type(body) == "string" then return 200, body end
    local msg = tostring(body)
    return msg:find("429") and 429 or 0, msg
end
function SV.fetch(pages)
    local base = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"
    local list, seen, cursor = {}, {}, nil
    for page = 1, pages or 4 do
        local url = base .. (cursor and ("&cursor=" .. HttpService:UrlEncode(cursor)) or "")
        local code, body
        for try = 0, 3 do
            SV.status = string.format("Fetching servers  ·  %d found", #list)
            code, body = SV.get(url)
            if code ~= 429 then break end
            local w = 12 * (try + 1)
            SV.status = string.format("Rate limited, waiting %ds  ·  %d found", w, #list)
            task.wait(w)
        end
        if code ~= 200 then break end
        local ok, dat = pcall(function() return HttpService:JSONDecode(body) end)
        if not (ok and type(dat) == "table" and type(dat.data) == "table") then break end
        for _, s in ipairs(dat.data) do
            if type(s) == "table" and s.id and not seen[s.id] and s.id ~= game.JobId and num(s.playing) < num(s.maxPlayers) then
                seen[s.id] = true
                list[#list + 1] = { id = s.id, playing = num(s.playing), max = num(s.maxPlayers), ping = num(s.ping) }
            end
        end
        cursor = dat.nextPageCursor
        if not cursor or cursor == "" then break end
        if page < (pages or 4) then task.wait(3) end
    end
    table.sort(list, function(a, b)
        if a.playing ~= b.playing then return a.playing < b.playing end
        return a.ping < b.ping
    end)
    return list
end
function SV.joinLowest(reason)
    if SV.busy then notify(L["Already looking for a server"]) return end
    SV.busy = true
    task.spawn(function()
        local ok, err = pcall(function()
            local list = SV.fetch(4)
            if #list == 0 then SV.status = L["No servers found"] notify(L["No servers found"]) return end
            SV.status = string.format("Found %d servers  ·  lowest %d/%d", #list, list[1].playing, list[1].max)
            local tries = 0
            for _, s in ipairs(list) do
                if not SV.tried[s.id] then
                    SV.tried[s.id] = true
                    tries = tries + 1
                    SV.status = string.format("Joining %d/%d server%s", s.playing, s.max, reason and ("  ·  " .. reason) or "")
                    notify(SV.status)
                    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, lp) end)
                    task.wait(10)
                    if tries >= 5 then break end
                end
            end
            SV.status = "Couldn't join, try again"
        end)
        if not ok then SV.status = "Failed: " .. tostring(err):sub(1, 50) end
        SV.busy = false
    end)
end
function SV.minRank()
    return (Opt and Opt.cc_staffrank and Opt.cc_staffrank.Value == "Developers Only") and 250 or 197
end
function SV.checkRank(p)
    if p == lp or SV.rank[p.UserId] ~= nil then return end
    SV.rank[p.UserId] = false
    task.spawn(function()
        local ok, r = pcall(function() return p:GetRankInGroup(SV.GROUP) end)
        if not ok then SV.rank[p.UserId] = nil return end
        local role = ""
        pcall(function() role = p:GetRoleInGroup(SV.GROUP) end)
        SV.rank[p.UserId] = r
        SV.role[p.UserId] = role
    end)
end
function SV.staffRole(p)
    if p == lp then return nil end
    if SV.WL[p.UserId] then return "Owner" end
    if p:GetAttribute("ConchDeveloper") == true then return "Developer" end
    local sr = p:GetAttribute("StaffRole")
    if type(sr) == "string" and sr ~= "" then return sr end
    if num(p:GetAttribute("ModerationTier")) >= 1 then return "Moderator" end
    local min = SV.minRank()
    local gr = num(p:GetAttribute("groupRank"))
    if gr >= min then return "Rank " .. gr end
    local r = SV.rank[p.UserId]
    if type(r) == "number" and r >= min then return tostring(SV.role[p.UserId] ~= "" and SV.role[p.UserId] or ("Rank " .. r)) end
    return nil
end
function SV.staffText()
    for _, p in ipairs(Players:GetPlayers()) do
        local role = SV.staffRole(p)
        if role then return p.DisplayName .. " (" .. role .. ")" end
    end
end
local FARMS = { "cc_drive", "cc_dq", "cc_crates", "cc_claim", "cc_clean", "cc_trivia", "cc_meteor", "cc_rebirth", "cc_upgrades", "cc_sell", "cc_drink", "cc_buypot" }
track(Players.PlayerRemoving:Connect(function(p) SV.rank[p.UserId] = nil SV.acted[p.UserId] = nil end))
function SV.loop()
    while RUNNING do
        pcall(function()
            for _, p in ipairs(Players:GetPlayers()) do SV.checkRank(p) end
            if on("cc_staff") then
                for _, p in ipairs(Players:GetPlayers()) do
                    local role = SV.staffRole(p)
                    if role and not SV.acted[p.UserId] then
                        SV.acted[p.UserId] = true
                        notify(L["Staff in server: "] .. p.DisplayName .. " (" .. role .. ")")
                        for _, k in ipairs(FARMS) do if on(k) then pcall(function() Toggles[k]:SetValue(false) end) end end
                        if on("cc_staffleave") then SV.joinLowest("Staff in server") end
                    end
                end
            end
            if on("cc_leavecap") and not SV.busy and Opt and Opt.cc_leavecount and #Players:GetPlayers() >= Opt.cc_leavecount.Value and os.clock() - (SV.capAt or 0) > 60 then
                SV.capAt = os.clock()
                SV.joinLowest("Server got crowded")
            end
            if on("cc_antiafk") then AFK.set(true) end
        end)
        task.wait(2)
    end
end
