local function unload()
    pcall(function() for _, k in ipairs(FARMS) do if on(k) then Toggles[k]:SetValue(false) end end end)
    pcall(function() AU.sync({ flags = { AutoSpawn = false, AutoOpen = false } }) end)
    pcall(DW.stop)
    pcall(function() if env.__CW_DCC_CLEAN then env.__CW_DCC_CLEAN() end end)
    pcall(function() Library:Unload() end)
end
