task.spawn(function()
    for _, k in ipairs({
        { "LuckyBlock", "OpenResult" }, { "Cleaning", "SessionState" }, { "Quests", "Sync" }, { "Quests", "ClaimResult" },
        { "Trivia", "Overview" }, { "Trivia", "Finished" }, { "Trivia", "Question" }, { "Trivia", "AnswerResult" },
        { "PotionShop", "StockSync" }, { "PotionShop", "RestockGranted" }, { "PotionShop", "BuyResult" }, { "Popups", "UpperNotification" },
    }) do listen(k[1], k[2]) end
    S.startCash = cashNum()
    S.startGems = num(val("Gems"))
    for _, fn in ipairs({ AU.loop, CC.loop, PR.loop, PR.rebirthLoop, PR.upgradeLoop, DW.loop, DW.manualLoop, DQ.loop, CL.loop, RW.loop, TV.loop, MT.loop, PO.loop, SV.loop }) do task.spawn(fn) end
end)
