if not DW.inWorld and not PL.base() then notify(L["Your plot was not found. Farms need your plot."]) end
task.spawn(function()
    local t0 = os.clock()
    local function set(lbl, txt) if lbl then pcall(function() lbl:SetText(txt) end) end end
    local function state(key, id, idle) return S.status[key] or (on(id) and L["Starting"] or (idle or L["Off"])) end
    local lastCars = 0
    while RUNNING do
        pcall(function()
            local mins = math.floor((os.clock() - t0) / 60)
            local cash = cashNum()
            local gems = num(val("Gems"))
            local away = DW.inWorld and L["Works at your collection"] or nil
            set(labels.crates, (away or state("crates", "cc_crates")) .. string.format(L["\nOpened %d  ·  Placed %d\nIn bag %d"], S.opened, count(val("PlacedLuckyBlocks")), count(val("LuckyBlocks"))) .. (S.lastCar and (L["\nLast: "] .. S.lastCar) or ""))
            set(labels.cash, string.format(L["$%s  ·  +$%s (%dm)\nCollected $%s"], abbrev(cash), abbrev(math.max(cash - (S.startCash or cash), 0)), mins, abbrev(S.claimed)))
            set(labels.progress, string.format(L["Rebirths %d  ·  +%d now\nUpgrades bought %d"], num(val("Rebirths")), S.rebirths, S.upgrades))
            set(labels.clean, (away or state("clean", "cc_clean")) .. string.format(L["\nWashed %d  ·  +%d gems"], S.cleaned, S.cleanGems))
            local rate = ""
            if DW.t0 and os.clock() - DW.t0 > 120 and (DW.gems or 0) > 0 then
                rate = string.format("\n~%s gems/hr", abbrev((DW.gems or 0) / ((os.clock() - DW.t0) / 3600)))
            end
            set(labels.drive, (DW.inWorld and state("drive", "cc_drive") or L["Go to Drive World first"]) .. string.format(L["\n%d mi  ·  +%d gems  ·  %d laps"], DW.miles or 0, DW.gems or 0, DW.legs) .. rate)
            local dqm = math.floor(num(val("DrivingMiles")))
            set(labels.dq, (S.status.dq or (on("cc_dq") and L["Checking"] or L["Off"])) .. string.format(L["\nMiles %d/%d"], math.min(dqm, DQ.REQ), DQ.REQ))
            set(labels.rw, string.format(L["Gems %s  ·  +%s\nClaimed %d"], abbrev(gems), abbrev(math.max(gems - (S.startGems or gems), 0)), S.quests))
            set(labels.trivia, (DW.inWorld and on("cc_trivia") and L["Works at your collection"] or state("trivia", "cc_trivia", L["Off"])) .. string.format(L["\nCorrect %d  ·  Known %d"], S.triviaRight, count(TV.bank)))
            local drops = #CollectionService:GetTagged("AdminMeteorDrop")
            set(labels.event, (drops > 0 and (L["Raining! "] .. drops .. L[" crates"]) or L["No crate rain now"]) .. string.format(L["\nGrabbed %d"], S.meteors))
            local stockTxt = {}
            for _, id in ipairs(SHOP_POTIONS) do if num(PO.stock[id]) > 0 then stockTxt[#stockTxt + 1] = (POT_NAME[id] or id) .. " " .. PO.stock[id] end end
            set(labels.shop, string.format(L["Gems %s  ·  Bought %d"], abbrev(gems), S.bought) .. (#stockTxt > 0 and (L["\nIn stock: "] .. table.concat(stockTxt, ", ")) or L["\nStock unknown"]))
            set(labels.drink, string.format(L["Drank %d"], S.drank))
            set(labels.safety, string.format(L["Players %d  ·  %s"], #Players:GetPlayers(), SV.status) .. (SV.staffText() and (L["\nStaff: "] .. SV.staffText()) or ""))
            local n = count(val("Cars"))
            if n ~= lastCars and Opt.cc_drcar then
                lastCars = n
                local list = DW.carList()
                local cur = Opt.cc_drcar.Value
                pcall(function() Opt.cc_drcar:SetValues(list) end)
                if not table.find(list, cur) then pcall(function() Opt.cc_drcar:SetValue("Best Car") end) end
            end
        end)
        task.wait(Library.Toggled == false and 2 or 0.5)
    end
end)

end
